WITH base AS (SELECT id, customer_id, device, browser, started_at, country, DATEDIFF(CURRENT_DATE(), started_at) AS days_since_started_at, COALESCE(browser, 'OTHER') AS browser_clean FROM sessions WHERE started_at >= DATE '2024-02-17' AND customer_id IS NOT NULL) SELECT * FROM (SELECT customer_id, country, days_since_started_at FROM base) src PIVOT (SUM(days_since_started_at) FOR country IN ('US', 'JP', 'UK'));
